mapper.select:
SELECT id, user_id, title, description, plan_date, plan_type, created_at, updated_at
FROM plans
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
UPDATE plans
SET title       = #{title},
    description = #{description},
    plan_date   = #{planDate},
    plan_type   = #{planType}
WHERE id      = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM plans
WHERE id      = #{id}
  AND user_id = #{userId}
